#!/bin/sh

#  OrcaSlicer gettext
#  Created by SoftFever on 27/5/23.
#

list_file="./localization/i18n/list.txt"
pot_file="./localization/i18n/OrcaSlicer.pot"
filtered_list=""
missing_list=""
generated_root_dir=""

report_missing_files()
{
    if [ -n "$missing_list" ] && [ -s "$missing_list" ]; then
        echo
        echo "Skipped missing source files listed in ${list_file}:"
        while IFS= read -r missing || [ -n "$missing" ]; do
            echo "  - $missing"
        done < "$missing_list"
    fi
}

cleanup_temp_files()
{
    [ -n "$filtered_list" ] && rm -f "$filtered_list"
    [ -n "$missing_list" ] && rm -f "$missing_list"
    [ -n "$generated_root_dir" ] && rm -rf "$generated_root_dir"
}

files_equal_ignoring_pot_date()
{
    file_a=$1
    file_b=$2
    norm_a=$(mktemp)
    norm_b=$(mktemp)

    sed '/^"POT-Creation-Date: /d' "$file_a" > "$norm_a"
    sed '/^"POT-Creation-Date: /d' "$file_b" > "$norm_b"

    if cmp -s "$norm_a" "$norm_b"; then
        rm -f "$norm_a" "$norm_b"
        return 0
    fi

    rm -f "$norm_a" "$norm_b"
    return 1
}

trap 'report_missing_files; cleanup_temp_files' EXIT

# Check for --full argument
FULL_MODE=false
for arg in "$@"
do
    if [ "$arg" = "--full" ]; then
        FULL_MODE=true
    fi
done

import { defineConfig } from 'vitest/config';
import { searchForWorkspaceRoot } from 'vite';
import react from '@vitejs/plugin-react';
import { viteSingleFile } from 'vite-plugin-singlefile';
import { fileURLToPath } from 'node:url';

const resources = fileURLToPath(new URL('../../../../../resources', import.meta.url));
const shared = fileURLToPath(new URL('../WebShared', import.meta.url));

// The bundle must be a single self-contained file: WKWebView does not load
// file: subresources reliably (POC lesson), so everything inlines into one
// index.html packaged at resources/jusprin/agent/index.html.
export default defineConfig({
  plugins: [react(), viteSingleFile()],
  resolve: {
    alias: {
      '@resources': resources,
      '@shared': shared,
    },
  },
  server: {
    port: 5173,
    strictPort: true,
    // The CSS loads icons from resources/ and fonts from WebShared/, both outside
    // this folder, which the dev server refuses (403) unless they are allowed.
    fs: { allow: [searchForWorkspaceRoot(process.cwd()), resources, shared] },
  },
  build: {
    outDir: fileURLToPath(new URL('../../../../../resources/jusprin/agent', import.meta.url)),
    // protocol.json lives in the same directory and must survive builds.
    emptyOutDir: false,
  },
  test: {
    environment: 'jsdom',
    globals: true,
    setupFiles: ['./src/test/setup.ts'],
  },
});
