#ifndef L
#define L(s) s
#endif
#ifndef _L_PLURAL
#define _L_PLURAL(s, plural, n) wording(s, plural, n)
#endif

namespace Slic3r::GUI::JusPrin::PrinterSetup {

namespace {

std::string first_of(const Preset& preset, const char* key)
{
    const auto* values = preset.config.option<ConfigOptionStrings>(key);
    return values != nullptr && !values->values.empty() ? values->values.front() : std::string();
    }
    return plates;
}

// The printers a filament's profile names, as a phrase for "Made for ...":
// each by its model's name where the profiles know it, by the name the
// profile gives otherwise (a person's own printer, say).
std::string made_for(const PresetBundle& bundle, const Preset& filament, const Wording& wording)
{
    std::vector<std::string> printers;
    if (const auto* names = filament.config.option<ConfigOptionStrings>("compatible_printers"))
        for (const std::string& name : names->values) {
            std::string shown = name;
            if (const Preset* printer = bundle.printers.find_preset(name, false); printer != nullptr && printer->name == name)
                if (const VendorProfile::PrinterModel* model = PresetUtils::system_printer_model(*printer))
                    shown = model->name;
            if (std::find(printers.begin(), printers.end(), shown) == printers.end())
                printers.push_back(shown);
        }
    if (printers.empty())
        // TRN The end of "Made for ...", on a filament the printer form offers that was made for other printers.
        return wording(L("other printers"));
    if (printers.size() == 1)
        // TRN The end of "Made for ...": %1% is a printer model, as in "Bambu Lab X1 Carbon".
        return Slic3r::format(wording(L("the %1%")), printers[0]);
    if (printers.size() == 2)
        // TRN The end of "Made for ...": %1% and %2% are printer models.
        return Slic3r::format(wording(L("the %1% and %2%")), printers[0], printers[1]);
    const unsigned others = unsigned(printers.size() - 2);
    // TRN The end of "Made for ...": %1% and %2% are printer models, %3% how many more the filament was made for.
    return Slic3r::format(_L_PLURAL("the %1%, %2% and %3% other printer", "the %1%, %2% and %3% other printers", others), printers[0],
                          printers[1], others);
}

} // namespace

