    if (characters > 120 || cleaned.find_first_of("\r\n") != std::string::npos) return false;
    (*conversation)["title"] = std::move(cleaned);
    (*conversation)["titleSource"] = generated ? "generated" : "manual";
    touch();
    return true;
}

